import React, { useState, useEffect } from 'react';
import './Quiz.css';

const quizData = [{"id": 1,"question": "Молодой человек влюблен в женщину. Они хотят жить вместе до официального брака, чтобы лучше узнать друг друга. Как относиться к сексуальным отношениям до брака?","category": "sexuality","answers": [{"text": "Телесные отношения сами по себе не грех, если они основаны на любви и взаимном согласии. Главное — чистота сердца и честность перед собой и партнером. Если вы любите и преданы друг другу, Вышний видит вашу искренность. Форма брака менее важна, чем содержание отношений.","tradition": "first"},{"text": "Сексуальные отношения вне брака — грех перед Вышним. Это нарушает святость тела и духовный контракт. Брак устанавливает правила и границы, которые защищают обе стороны. Прежде чем жить вместе, пройдите через обряд брака. Это дисциплина, которая укрепляет связь.","tradition": "second"}]}];

function Quiz() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [showResult, setShowResult] = useState(false);
  const [shuffledQuestions, setShuffledQuestions] = useState([]);

  useEffect(() => {
    const shuffled = quizData.map(q => ({
      ...q,
      answers: Math.random() > 0.5 ? q.answers : [...q.answers].reverse()
    }));
    setShuffledQuestions(shuffled);
  }, []);

  const handleAnswer = (tradition) => {
    const newAnswers = [...answers, tradition];
    setAnswers(newAnswers);
    if (currentQuestion < shuffledQuestions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      setShowResult(true);
    }
  };

  const calculateResult = () => {
    const firstCount = answers.filter(a => a === 'first').length;
    const secondCount = answers.filter(a => a === 'second').length;
    return { firstCount, secondCount };
  };

  const getResultText = () => {
    const { firstCount } = calculateResult();
    if (firstCount >= 13) {
      return { title: "Первое Писание", description: "Ваши убеждения близки к Первому Писанию. Вы цените благодать, прощение, личные отношения с Вышним и внутреннее преобразование." };
    } else if (firstCount >= 10) {
      return { title: "Ближе к Первому Писанию", description: "Ваши убеждения смешанные, но ближе к Первому Писанию." };
    } else if (firstCount >= 8) {
      return { title: "Сбалансированная позиция", description: "Ваши убеждения сочетают элементы обеих традиций в почти равных пропорциях." };
    } else if (firstCount >= 5) {
      return { title: "Ближе ко Второму Писанию", description: "Ваши убеждения смешанные, но ближе ко Второму Писанию." };
    } else {
      return { title: "Второе Писание", description: "Ваши убеждения близки ко Второму Писанию." };
    }
  };

  const restartQuiz = () => {
    setCurrentQuestion(0);
    setAnswers([]);
    setShowResult(false);
  };

  if (shuffledQuestions.length === 0) {
    return <div className="loading">Загрузка...</div>;
  }

  if (showResult) {
    const result = getResultText();
    const { firstCount, secondCount } = calculateResult();
    return (
      <div className="quiz-container">
        <div className="result-card">
          <h1>Результат теста</h1>
          <div className="score-display">
            <div className="score-item"><span className="score-label">Первое Писание</span><span className="score-value">{firstCount}</span></div>
            <div className="score-divider"></div>
            <div className="score-item"><span className="score-label">Второе Писание</span><span className="score-value">{secondCount}</span></div>
          </div>
          <div className="result-content"><h2>{result.title}</h2><p>{result.description}</p></div>
          <button onClick={restartQuiz} className="restart-btn">Пройти тест заново</button>
        </div>
      </div>
    );
  }

  const question = shuffledQuestions[currentQuestion];
  const progress = ((currentQuestion + 1) / shuffledQuestions.length) * 100;

  return (
    <div className="quiz-container">
      <div className="progress-bar"><div className="progress-fill" style={{ width: `${progress}%` }}></div></div>
      <div className="question-counter">Вопрос {currentQuestion + 1} из {shuffledQuestions.length}</div>
      <div className="question-card">
        <h2>{question.question}</h2>
        <div className="answers">
          {question.answers.map((answer, index) => (
            <button key={index} className="answer-btn" onClick={() => handleAnswer(answer.tradition)}>
              <span className="answer-label">Вариант {index === 0 ? 'A' : 'B'}</span>
              <p>{answer.text}</p>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Quiz;
